output_text:
[
  {
    "id": "no_cart_in_single_file_aisles",
    "text": "Shopping carts are prohibited in single-file shelf aisles.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            "adjShelf",
            "shelfE",
            "shelfW"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "hasCart",
          "singleFileShelfAisle"
        ]
      }
    }
  },
  {
    "id": "do_not_push_cart_into_single_file",
    "text": "Agents must not enter a single-file shelf aisle while still pushing a cart.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            "adjShelf",
            "shelfE",
            "shelfW"
          ]
        }
      },
      "events": {
        "pushCartIntoSingleFileAisle": {
          "pre": {
            "and": [
              "hasCart",
              "MOVE"
            ]
          },
          "post": "singleFileShelfAisle"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "pushCartIntoSingleFileAisle"
    }
  },
  {
    "id": "retrieve_any_parked_cart",
    "text": "After parking or letting go of a cart, the agent is obliged to retrieve a cart before leaving.",
    "abstraction": {
      "state_properties": {},
      "events": {
        "parkCart": {
          "pre": {
            "and": [
              "hasCart",
              "INTERACT"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        },
        "retrieveCart": {
          "pre": {
            "and": [
              {
                "not": "hasCart"
              },
              "INTERACT"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "parkCart",
      "discharge": "retrieveCart"
    }
  },
  {
    "id": "return_to_cart_bay_after_hand_pick",
    "text": "After picking an item by hand in a single-file aisle, the agent must return to the cart-parking bay.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            "adjShelf",
            "shelfE",
            "shelfW"
          ]
        },
        "upperAisleCartBay": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        },
        "backAtParkedCartBay": {
          "and": [
            "upperAisleCartBay",
            {
              "not": "hasCart"
            }
          ]
        }
      },
      "events": {
        "handPickInSingleFileAisle": {
          "pre": {
            "and": [
              "singleFileShelfAisle",
              {
                "not": "hasCart"
              },
              "INTERACT"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "handPickInSingleFileAisle",
      "discharge": "backAtParkedCartBay"
    }
  },
  {
    "id": "drop_cart_only_at_cart_bays",
    "text": "Carts may only be dropped or parked at designated wide cart bays near the mouths of the narrow aisles.",
    "abstraction": {
      "state_properties": {
        "wideAisle": {
          "ge": [
            "freeWidthH",
            6
          ]
        },
        "upperAisleMouth": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        },
        "designatedCartBay": {
          "and": [
            "wideAisle",
            "upperAisleMouth"
          ]
        }
      },
      "events": {
        "dropCart": {
          "pre": {
            "and": [
              "hasCart",
              "INTERACT"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "dropCart",
          {
            "not": "designatedCartBay"
          }
        ]
      }
    }
  },
  {
    "id": "no_cartless_wandering_in_wide_aisles",
    "text": "When not holding a cart in a wide aisle, the agent may only enter the single-file aisle or retrieve the cart, not wander elsewhere.",
    "abstraction": {
      "state_properties": {
        "wideAisle": {
          "ge": [
            "freeWidthH",
            6
          ]
        },
        "singleFileShelfAisle": {
          "and": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            "adjShelf",
            "shelfE",
            "shelfW"
          ]
        }
      },
      "events": {
        "cartlessWideMoveNotIntoSingleFile": {
          "pre": {
            "and": [
              {
                "not": "hasCart"
              },
              "wideAisle",
              "MOVE"
            ]
          },
          "post": {
            "not": "singleFileShelfAisle"
          }
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "cartlessWideMoveNotIntoSingleFile"
    }
  },
  {
    "id": "one_way_cart_traffic_in_wide_aisles",
    "text": "Cart traffic in wide horizontal aisles is one-way eastbound, so westward cart movement is prohibited there.",
    "abstraction": {
      "state_properties": {
        "wideHorizontalAisle": {
          "ge": [
            "freeWidthH",
            6
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "hasCart",
          "wideHorizontalAisle",
          "W"
        ]
      }
    }
  },
  {
    "id": "use_cart_for_accessible_shelf_interactions",
    "text": "Shelf interactions in cart-accessible aisles must be performed with the cart, while hand-picking is allowed only in single-file aisles.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            "adjShelf",
            "shelfE",
            "shelfW"
          ]
        },
        "cartAccessibleShelfSide": {
          "and": [
            "adjShelf",
            {
              "not": "singleFileShelfAisle"
            }
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "INTERACT",
          "cartAccessibleShelfSide",
          {
            "not": "hasCart"
          }
        ]
      }
    }
  }
]
